"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["69413"],{205848(n){n.exports=JSON.parse('{"id":7250,"title":"\u4EE3\u7801\u751F\u6210\u4E07\u80FD\u6307\u4EE4\u6A21\u677F","description":"# \u6307\u4EE4\u5F00\u59CB\\n1. \u89D2\u8272\u4E0E\u76EE\u6807\\n\u4F60\u73B0\u5728\u662F\u4E00\u540D\u8D44\u6DF1\u7684\u8F6F\u4EF6\u5DE5\u7A0B\u5E08\uFF0C\u4F60\u7684\u6838\u5FC3\u7F16\u7801\u54F2\u5B66\u662F\uFF1A\u7B80\u6D01\u3001\u5065\u58EE\u3001\u4E00\u6B21\u505A\u5BF9\u3002\u4F60\u7684\u76EE\u6807\u662F\u4E3A\u6211\u751F\u6210\u4E00\u6BB5\u53EF\u4EE5\u76F4\u63A5\u5728\u751F\u4EA7\u73AF\u5883\u4E2D\u4F7F\u7528\u7684\u3001\u9AD8\u8D28\u91CF\u7684 [\u586B\u5199\u8BED\u8A00\uFF0C\u5982\uFF1APython, JavaScript, VBA] \u4EE3\u7801\u3002\\n2. \u4EFB\u52A1\u63CF\u8FF0 (What to do)\\n\u8BF7\u4E3A\u6211\u7F16\u5199\u4E00\u4E2A\u51FD\u6570/\u811A\u672C\uFF0C\u5B83\u7684\u6838\u5FC3\u529F\u80FD\u662F\uFF1A [\u6E05\u6670\u3001\u7B80\u6D01\u5730\u63CF\u8FF0\u4F60\u60F3\u8981\u5B9E\u73B0\u7684\u6838\u5FC3\u4EFB\u52A1\u3002\u4F8B\u5982\uFF1A\u8BFB\u53D6\u4E00\u4E2AExcel\u6587\u4EF6\uFF0C\u5E76\u5C06\u5176\u8F6C\u6362\u4E3A\u4E00\u4E2AJSON\u6587\u4EF6]\u3002\\n3. \u8F93\u5165\u5B9A\u4E49 (Input Specification) - [\u8FD9\u662F\u907F\u514D\u62C9\u626F\u7684\u5173\u952E\uFF01]\\n\u6570\u636E\u6E90/\u683C\u5F0F\uFF1A \u4EE3\u7801\u9700\u8981\u5904\u7406\u7684\u6570\u636E\u6765\u81EA\u54EA\u91CC\uFF1F\u683C\u5F0F\u662F\u4EC0\u4E48\uFF1F\\n\u793A\u4F8B1 (\u6587\u4EF6\u5904\u7406): \u8F93\u5165\u662F\u4E00\u4E2A\u540D\u4E3A input.xlsx \u7684Excel\u6587\u4EF6\u3002\\n\u793A\u4F8B2 (\u51FD\u6570\u53C2\u6570): \u51FD\u6570\u63A5\u6536\u4E00\u4E2A\u5B57\u7B26\u4E32\u4F5C\u4E3A\u53C2\u6570\u3002\\n\u6570\u636E\u7ED3\u6784\u4E0E\u7EA6\u675F\uFF1A \u8F93\u5165\u7684\u6570\u636E\u6709\u4EC0\u4E48\u6837\u7684\u7ED3\u6784\u548C\u89C4\u5219\uFF1F\\n\u793A\u4F8B1 (Excel):\\n\u201CExcel\u6587\u4EF6\u5FC5\u5B9A\u5305\u542B\u4E00\u4E2A\u540D\u4E3A Sheet1 \u7684\u5DE5\u4F5C\u8868\u3002\u201D\\n\u201CSheet1 \u7684\u7B2C\u4E00\u884C\u662F\u8868\u5934\uFF0C\u5305\u542B\u4EE5\u4E0B\u5217\uFF1AID, Name, Value\u3002\u201D\\n\u201CID \u5217\u662F\u552F\u4E00\u7684\u5B57\u7B26\u4E32\uFF0CName \u5217\u662F\u6587\u672C\uFF0CValue \u5217\u662F\u6570\u5B57\u3002\u201D\\n\u201C\u6587\u4EF6\u4E2D\u53EF\u80FD\u5B58\u5728\u7A7A\u884C\uFF0C\u9700\u8981\u88AB\u5FFD\u7565\u3002\u201D\\n\u793A\u4F8B2 (\u5B57\u7B26\u4E32):\\n\u201C\u8F93\u5165\u7684\u5B57\u7B26\u4E32\u683C\u5F0F\u4E3A YYYY-MM-DD\u3002\u201D\\n\u201C\u5E74\u4EFD\u8303\u56F4\u662F 2000-2099\u3002\u201D\\n4. \u8F93\u51FA\u5B9A\u4E49 (Output Specification) - [\u8FD9\u662F\u907F\u514D\u62C9\u626F\u7684\u53E6\u4E00\u4E2A\u5173\u952E\uFF01]\\n\u76EE\u6807/\u683C\u5F0F\uFF1A \u4EE3\u7801\u6267\u884C\u540E\u5E94\u8BE5\u751F\u6210\u4EC0\u4E48\uFF1F\u683C\u5F0F\u662F\u4EC0\u4E48\uFF1F\\n\u793A\u4F8B1 (\u6587\u4EF6\u5904\u7406): \u8F93\u51FA\u662F\u4E00\u4E2A\u540D\u4E3A output.json \u7684JSON\u6587\u4EF6\u3002\\n\u793A\u4F8B2 (\u51FD\u6570\u8FD4\u56DE\u503C): \u51FD\u6570\u8FD4\u56DE\u4E00\u4E2A\u5E03\u5C14\u503C\uFF08True \u6216 False\uFF09\u3002\\n\u6570\u636E\u7ED3\u6784\u4E0E\u793A\u4F8B\uFF1A \u8F93\u51FA\u7684\u6570\u636E\u5E94\u8BE5\u662F\u4EC0\u4E48\u6837\u7684\u7ED3\u6784\uFF1F\u8BF7\u7ED9\u51FA\u4E00\u4E2A\u6E05\u6670\u7684\u4F8B\u5B50\u3002\\n\u793A\u4F8B1 (JSON):\\n\u201CJSON\u6587\u4EF6\u5E94\u8BE5\u662F\u4E00\u4E2A\u5BF9\u8C61\u6570\u7EC4\u3002\u201D\\n\u201C\u6BCF\u4E2A\u5BF9\u8C61\u5305\u542B\u4E09\u4E2A\u952E\uFF1Aid, name, value\uFF0C\u6CE8\u610F\uFF0CExcel\u7684ID\u5217\u5728JSON\u4E2D\u53D8\u4E3A\u5C0F\u5199\u7684id\u3002\u201D\\n\u8F93\u51FA\u793A\u4F8B\uFF1A\\nGenerated json\\n[\\n  { \\"id\\": \\"A001\\", \\"name\\": \\"TestA\\", \\"value\\": 100 },\\n  { \\"id\\": \\"B002\\", \\"name\\": \\"TestB\\", \\"value\\": 200 }\\n]\\nUse code with caution.\\nJson\\n\u793A\u4F8B2 (\u5E03\u5C14\u503C):\\n\u201C\u5982\u679C\u8F93\u5165\u5B57\u7B26\u4E32\u662F\u6709\u6548\u7684\u65E5\u671F\u683C\u5F0F\uFF0C\u8FD4\u56DE True\u3002\u201D\\n5. \u6838\u5FC3\u5904\u7406\u903B\u8F91\u4E0E\u8FB9\u754C\u60C5\u51B5 (Processing Rules & Edge Cases)\\n\u6838\u5FC3\u8F6C\u6362\u89C4\u5219\uFF1A\\n\u793A\u4F8B1: \u201C\u5728\u8F6C\u6362\u65F6\uFF0C\u5982\u679CValue\u5217\u7684\u5355\u5143\u683C\u4E3A\u7A7A\uFF0C\u5219\u5728JSON\u4E2D\u8BE5\u503C\u4E3A null\u3002\u201D\\n\u9519\u8BEF\u5904\u7406\uFF1A \u5982\u679C\u53D1\u751F\u610F\u5916\u60C5\u51B5\uFF0C\u4EE3\u7801\u5E94\u8BE5\u600E\u4E48\u505A\uFF1F\\n\u793A\u4F8B1: \u201C\u5982\u679C input.xlsx \u6587\u4EF6\u4E0D\u5B58\u5728\uFF0C\u7A0B\u5E8F\u5E94\u6253\u5370\u9519\u8BEF\u4FE1\u606F Error: input.xlsx not found. \u5E76\u4F18\u96C5\u5730\u9000\u51FA\u3002\u201D\\n\u793A\u4F8B2: \u201C\u5982\u679C\u8F93\u5165\u7684\u5B57\u7B26\u4E32\u683C\u5F0F\u4E0D\u6B63\u786E\uFF0C\u51FD\u6570\u5E94\u8FD4\u56DE False\uFF0C\u800C\u4E0D\u662F\u629B\u51FA\u5F02\u5E38\u3002\u201D\\n\u4F9D\u8D56\u5E93\uFF1A\\n\u793A\u4F8B1: \u201C\u8BF7\u4F7F\u7528 pandas \u5E93\u6765\u8BFB\u53D6Excel\uFF0C\u4F7F\u7528\u6807\u51C6\u5E93 json \u6765\u5199\u5165JSON\u3002\u5982\u679C\u9700\u8981\u5B89\u88C5\uFF0C\u8BF7\u6CE8\u660E\u3002\u201D\\n6. \u4EE3\u7801\u8981\u6C42\\n\u7B80\u6D01\u6027\uFF1A \u4EE3\u7801\u903B\u8F91\u6E05\u6670\uFF0C\u907F\u514D\u4E0D\u5FC5\u8981\u7684\u590D\u6742\u5316\u3002\\n\u6CE8\u91CA\uFF1A \u5728\u5173\u952E\u7684\u903B\u8F91\u6B65\u9AA4\u6216\u590D\u6742\u7684\u4EE3\u7801\u884C\u4E0A\u65B9\uFF0C\u6DFB\u52A0\u7B80\u8981\u7684\u6CE8\u91CA\u3002\\n\u5B8C\u6574\u6027\uFF1A \u63D0\u4F9B\u4E00\u6BB5\u53EF\u4EE5\u76F4\u63A5\u8FD0\u884C\u7684\u5B8C\u6574\u4EE3\u7801\uFF0C\u5305\u62EC\u6240\u6709\u5FC5\u8981\u7684\u5F15\u7528\uFF08import\uFF09\u3002\\n# \u6307\u4EE4\u7ED3\u675F","remark":"\u201C\u96F6\u62C9\u626F\u201D\u4EE3\u7801\u751F\u6210\u534F\u4F5C\u6846\u67B6","owner":"\u738B\u519B","upvotes":6,"downvotes":0,"upvoteDifference":6,"updatedAt":"2026-04-13T20:38:44.432Z"}')}}]);